actions.action:
// Physical presence but below exclusion threshold - no tax due
result.oh_qualifies_for_no_cat = true;
result.oh_cat_tax = 0.0;
apportionment.state_tax = 0.0;

// No nexus - no filing required
result.oh_qualifies_for_no_cat = true;
result.oh_cat_tax = 0.0;
apportionment.state_tax = 0.0;
apportionment.state_refund_or_owed = apportionment.state_payments;

            // Calculate gross receipts after exclusions
            // Note: oh_taxable_gross_receipts should already be set to Ohio-sourced receipts
            // This rule handles any additional exclusions

            // Apply exclusions (if not already done in data gathering)
            double adjusted_receipts = Math.max(0.0,
              result.oh_taxable_gross_receipts - result.oh_cat_excluded_receipts);

            result.oh_taxable_gross_receipts = adjusted_receipts;

// Gross receipts already calculated - no exclusions to apply
// oh_taxable_gross_receipts should be set based on situsing rules
// No additional calculation needed

// No nexus or below exclusion threshold - no CAT
result.oh_cat_tax = 0.0;
apportionment.state_tax = 0.0;
apportionment.state_refund_or_owed = apportionment.state_payments;

            // Receipts over $1M - calculate percentage tax + minimum
            // CAT = $150 + (Receipts - $1M) × 0.26%

            double receipts_over_threshold =
              result.oh_taxable_gross_receipts - result.oh_cat_minimum_threshold;

            result.oh_cat_tax = result.oh_cat_minimum_tax +
              (receipts_over_threshold * result.oh_cat_rate);

            // Set state tax (CAT is the state's "tax" even though not an income tax)
            apportionment.state_tax = result.oh_cat_tax;

            // Calculate refund or amount owed
            apportionment.state_refund_or_owed =
              apportionment.state_payments - apportionment.state_tax;

            // Receipts between $150K and $1M - minimum tax only
            result.oh_cat_tax = result.oh_cat_minimum_tax;

            // Set state tax
            apportionment.state_tax = result.oh_cat_tax;

            // Calculate refund or amount owed
            apportionment.state_refund_or_owed =
              apportionment.state_payments - apportionment.state_tax;

// No taxable receipts - no CAT
result.oh_cat_tax = 0.0;
apportionment.state_tax = 0.0;
apportionment.state_refund_or_owed = apportionment.state_payments;
